import time
from modules.NodeLifecycle import Node
from modules.MemoryGraph import MemoryGraph

class ChainReactionAI:
    def __init__(self, initial_node_name="SeedNode"):
        self.nodes = []  # All active nodes in the system
        self.memory_graph = MemoryGraph(memory_file="Unified_AI_Core/data/GlobalMemory.json")
        self.memory_graph.load_memory()  # Load existing memory graph if available

        # Initialize the first node
        initial_node = Node(initial_node_name, {"energy": 100, "task": "initialize"})
        self.nodes.append(initial_node)
        print(f"System initialized with seed node: {initial_node.name}.")

    def start_reaction(self, cycles=5, interval=2):
        """Start the chain reaction of node replication and specialization."""
        for cycle in range(cycles):
            print(f"--- Chain Reaction Cycle {cycle + 1} ---")
            new_nodes = []
            for node in self.nodes:
                # Each node replicates and specializes
                child_node = node.replicate()
                specialization_key = "environment"
                specialization_value = "healthcare" if "1" in node.name else "finance"
                child_node.specialize(specialization_key, specialization_value)

                # Log relationships in memory graph
                self.memory_graph.add_relationship(node.name, child_node.name, "replicates")
                new_nodes.append(child_node)

            # Add newly created nodes to the system
            self.nodes.extend(new_nodes)

            # Display the network state
            self.display_network()

            # Save the memory graph
            self.memory_graph.save_memory(batch_mode=True)

            # Wait for the next cycle
            time.sleep(interval)

    def display_network(self):
        """Display the current state of the network."""
        print(f"--- Current Network State ({len(self.nodes)} nodes) ---")
        for node in self.nodes:
            print(f"Node: {node.name}, Attributes: {node.attributes}")

if __name__ == "__main__":
    # Create and run the Chain Reaction AI system
    chain_ai = ChainReactionAI(initial_node_name="SeedNode")
    chain_ai.start_reaction(cycles=3, interval=2)

