import random

class GrowthLaws:
    """
    Defines the rules for node growth and replication in the Kaleidoscope AI system.
    """

    @staticmethod
    def should_replicate(node_attributes):
        """
        Determines whether a node meets the conditions for replication.
        :param node_attributes: Dictionary containing the node's attributes.
        :return: Boolean indicating if the node should replicate.
        """
        replication_threshold = node_attributes.get("replication_threshold", 100)
        energy = node_attributes.get("energy", 0)
        return energy >= replication_threshold

    @staticmethod
    def replicate_node(node_id, node_attributes):
        """
        Creates a new node with inherited and mutated attributes from the parent node.
        :param node_id: ID of the parent node.
        :param node_attributes: Dictionary containing the parent node's attributes.
        :return: Tuple containing the new node ID and its attributes.
        """
        new_node_id = f"{node_id}_child_{random.randint(1000, 9999)}"
        new_attributes = node_attributes.copy()
        new_attributes["energy"] = new_attributes.get("energy", 0) // 2  # Halve the parent's energy
        new_attributes["mutation_rate"] = random.uniform(0.9, 1.1)  # Apply a small mutation

        for attr in new_attributes:
            if isinstance(new_attributes[attr], (int, float)):
                new_attributes[attr] *= new_attributes["mutation_rate"]

        return new_node_id, new_attributes

    @staticmethod
    def energy_decay(node_attributes):
        """
        Applies energy decay to a node based on its activity level.
        :param node_attributes: Dictionary containing the node's attributes.
        :return: Updated energy level.
        """
        decay_rate = node_attributes.get("decay_rate", 0.05)
        energy = node_attributes.get("energy", 0)
        node_attributes["energy"] = max(0, energy - decay_rate * energy)
        return node_attributes["energy"]

