import heapq
from typing import List, Dict

class InsightRanker:
    """
    Dynamically ranks insights based on relevance, impact, and novelty.
    Helps prioritize high-value insights for decision-making.
    """

    def __init__(self):
        self.insight_heap: List[tuple] = []  # Min-heap to manage ranked insights
        self.insight_map: Dict[str, dict] = {}  # Map for quick access to insight details

    def add_insight(self, insight_id: str, relevance: float, impact: float, novelty: float):
        """
        Adds a new insight to the ranking system.
        :param insight_id: Unique identifier for the insight.
        :param relevance: Score for relevance (0.0 to 1.0).
        :param impact: Score for impact (0.0 to 1.0).
        :param novelty: Score for novelty (0.0 to 1.0).
        """
        score = self._calculate_priority_score(relevance, impact, novelty)
        self.insight_heap.append((-score, insight_id))  # Use negative score for max-heap behavior
        heapq.heapify(self.insight_heap)

        # Store the detailed insight data
        self.insight_map[insight_id] = {
            "relevance": relevance,
            "impact": impact,
            "novelty": novelty,
            "score": score,
        }
        print(f"Insight '{insight_id}' added with score {score:.2f}.")

    def _calculate_priority_score(self, relevance: float, impact: float, novelty: float) -> float:
        """
        Calculates a priority score based on weighted factors.
        :param relevance: Relevance score.
        :param impact: Impact score.
        :param novelty: Novelty score.
        :return: Priority score.
        """
        weights = {"relevance": 0.4, "impact": 0.4, "novelty": 0.2}  # Adjustable weights
        score = (
            weights["relevance"] * relevance +
            weights["impact"] * impact +
            weights["novelty"] * novelty
        )
        return score

    def get_top_insights(self, n: int = 5) -> List[Dict]:
        """
        Retrieves the top N insights based on their priority scores.
        :param n: Number of top insights to retrieve.
        :return: List of top insights with details.
        """
        top_insights = heapq.nlargest(n, self.insight_heap)
        return [
            {"id": insight_id, **self.insight_map[insight_id]}
            for _, insight_id in top_insights
        ]

    def update_insight(self, insight_id: str, relevance: float = None, impact: float = None, novelty: float = None):
        """
        Updates an existing insight's scores and recalculates its rank.
        :param insight_id: Unique identifier for the insight.
        :param relevance: New relevance score (optional).
        :param impact: New impact score (optional).
        :param novelty: New novelty score (optional).
        """
        if insight_id not in self.insight_map:
            raise ValueError(f"Insight '{insight_id}' not found.")

        # Update scores
        if relevance is not None:
            self.insight_map[insight_id]["relevance"] = relevance
        if impact is not None:
            self.insight_map[insight_id]["impact"] = impact
        if novelty is not None:
            self.insight_map[insight_id]["novelty"] = novelty

        # Recalculate the priority score
        updated_score = self._calculate_priority_score(
            self.insight_map[insight_id]["relevance"],
            self.insight_map[insight_id]["impact"],
            self.insight_map[insight_id]["novelty"],
        )
        self.insight_map[insight_id]["score"] = updated_score

        # Update the heap
        self.insight_heap = [
            (-self.insight_map[i]["score"], i) for i in self.insight_map
        ]
        heapq.heapify(self.insight_heap)
        print(f"Insight '{insight_id}' updated with new score {updated_score:.2f}.")

    def remove_insight(self, insight_id: str):
        """
        Removes an insight from the ranking system.
        :param insight_id: Unique identifier for the insight to remove.
        """
        if insight_id in self.insight_map:
            del self.insight_map[insight_id]
            self.insight_heap = [
                (-self.insight_map[i]["score"], i) for i in self.insight_map
            ]
            heapq.heapify(self.insight_heap)
            print(f"Insight '{insight_id}' removed.")

    def display_insights(self):
        """
        Displays all insights currently in the ranking system.
        """
        print("Current Insights:")
        for insight_id, details in self.insight_map.items():
            print(
                f"ID: {insight_id}, Relevance: {details['relevance']:.2f}, "
                f"Impact: {details['impact']:.2f}, Novelty: {details['novelty']:.2f}, "
                f"Score: {details['score']:.2f}"
            )

# Example usage
