import networkx as nx

class MirroredNetwork:
    """
    Implements parallel mirrored networks for cross-validation and redundancy.
    Synchronizes and validates data between primary and secondary networks.
    """

    def __init__(self):
        self.primary_network = nx.DiGraph()  # Primary network
        self.secondary_network = nx.DiGraph()  # Secondary network

    def add_node(self, node_id, attributes=None):
        """
        Adds a node to both networks.
        :param node_id: Unique identifier for the node.
        :param attributes: Optional dictionary of node attributes.
        """
        for network in [self.primary_network, self.secondary_network]:
            if not network.has_node(node_id):
                network.add_node(node_id, **(attributes or {}))
        print(f"Node '{node_id}' added to both networks.")

    def add_relationship(self, source, target, weight=1.0):
        """
        Adds or updates a relationship in both networks.
        :param source: Source node ID.
        :param target: Target node ID.
        :param weight: Weight of the relationship.
        """
        for network in [self.primary_network, self.secondary_network]:
            if network.has_edge(source, target):
                network[source][target]['weight'] += weight
            else:
                network.add_edge(source, target, weight=weight)
        print(f"Relationship added: {source} -> {target} (weight: {weight})")

    def sync_networks(self):
        """
        Synchronizes data between the primary and secondary networks.
        """
        for node in self.primary_network.nodes:
            p_attrs = self.primary_network.nodes[node]
            s_attrs = self.secondary_network.nodes[node]

            combined_attrs = {
                key: (p_attrs.get(key, 0) + s_attrs.get(key, 0)) / 2
                for key in set(p_attrs.keys()).union(s_attrs.keys())
            }

            nx.set_node_attributes(self.primary_network, {node: combined_attrs})
            nx.set_node_attributes(self.secondary_network, {node: combined_attrs})

        for edge in self.primary_network.edges:
            if self.secondary_network.has_edge(*edge):
                p_weight = self.primary_network[edge[0]][edge[1]]['weight']
                s_weight = self.secondary_network[edge[0]][edge[1]]['weight']

                combined_weight = (p_weight + s_weight) / 2

                self.primary_network[edge[0]][edge[1]]['weight'] = combined_weight
                self.secondary_network[edge[0]][edge[1]]['weight'] = combined_weight

        print("Networks synchronized.")

    def validate(self):
        """
        Validates consistency between the primary and secondary networks.
        :return: Boolean indicating if the networks are consistent.
        """
        for node in self.primary_network.nodes:
            if self.primary_network.nodes[node] != self.secondary_network.nodes[node]:
                return False

        for edge in self.primary_network.edges:
            if not self.secondary_network.has_edge(*edge):
                return False

            if (
                self.primary_network[edge[0]][edge[1]]['weight'] !=
                self.secondary_network[edge[0]][edge[1]]['weight']
            ):
                return False

        return True

    def visualize(self):
        """
        Visualizes both networks side by side.
        """
        import matplotlib.pyplot as plt

        fig, axes = plt.subplots(1, 2, figsize=(12, 6))

        pos_primary = nx.spring_layout(self.primary_network)
        nx.draw(self.primary_network, pos_primary, ax=axes[0], with_labels=True, node_color="skyblue", font_size=10)
        axes[0].set_title("Primary Network")

        pos_secondary = nx.spring_layout(self.secondary_network)
        nx.draw(self.secondary_network, pos_secondary, ax=axes[1], with_labels=True, node_color="lightgreen", font_size=10)
        axes[1].set_title("Secondary Network")

        plt.show()

# Example usage
