# core/NodeManager.py
import ray
from core.Node import Node

@ray.remote
class NodeManager:
    def __init__(self):
        self.nodes = {}

    def add_node(self, node_id, task, datasets):
        if node_id in self.nodes:
            return f"Node {node_id} already exists."
        node = Node.remote(node_id, task, datasets)
        self.nodes[node_id] = node
        return f"Node {node_id} added."

    def distribute_work(self):
        results = []
        for node_id, node in self.nodes.items():
            result = ray.get(node.explore_data.remote())
            results.append({node_id: result})
        return results

    def get_network_status(self):
        """
        Get the status of all nodes in the network.

        Returns:
            dict: Status of each node, including memory usage and energy levels.
        """
        statuses = {}
        for node_id, node in self.nodes.items():
            try:
                statuses[node_id] = ray.get(node.get_status.remote())
            except Exception as e:
                statuses[node_id] = f"Error retrieving status: {e}"
        return statuses

    def replicate_node(self, node_id):
        """
        Trigger replication for a specific node.

        Args:
            node_id (str): Identifier of the node to replicate.

        Returns:
            str: Status of the replication process.
        """
        if node_id not in self.nodes:
            return f"Node {node_id} not found in the network."

        try:
            replication_status = ray.get(self.nodes[node_id].replicate.remote())
            return replication_status
        except Exception as e:
            return f"Error during replication: {e}"

    def remove_node(self, node_id):
        """
        Remove a node from the network.

        Args:
            node_id (str): Identifier of the node to remove.

        Returns:
            str: Status of the removal.
        """
        if node_id not in self.nodes:
            return f"Node {node_id} not found in the network."

        del self.nodes[node_id]
        return f"Node {node_id} successfully removed from the network."

    def shutdown(self):
        """
        Gracefully shut down all nodes in the network.

        Returns:
            str: Status of the shutdown process.
        """
        for node_id, node in self.nodes.items():
            try:
                ray.kill(node)
            except Exception as e:
                print(f"Error shutting down node {node_id}: {e}")
        self.nodes.clear()
        return "All nodes have been shut down."
import threading
import time
import queue
import random
from typing import Dict, Any, Callable, List
from communication.NodeCommunication import NodeCommunication


class NodeManager:
    """
    Manages nodes, assigns tasks, tracks states, and handles recovery.
    """

    def __init__(self):
        self.nodes: Dict[str, NodeCommunication] = {}
        self.node_states: Dict[str, str] = {}  # node_id -> state: active, idle, failed
        self.task_queue = queue.Queue()
        self.lock = threading.Lock()
        self.task_processing_interval = 2  # seconds

        # Start the node health monitoring thread
        self._health_monitor_thread = threading.Thread(target=self._monitor_node_health, daemon=True)
        self._health_monitor_thread.start()

    def create_node(self, node_id: str):
        """
        Creates a new node and registers it in the system.
        :param node_id: Unique ID of the node.
        """
        with self.lock:
            if node_id not in self.nodes:
                new_node = NodeCommunication(node_id)
                self.nodes[node_id] = new_node
                self.node_states[node_id] = "idle"
                print(f"[NodeManager] Node '{node_id}' created and registered.")
            else:
                print(f"[NodeManager] Node '{node_id}' already exists.")

    def assign_task(self, node_id: str, task: Dict[str, Any]):
        """
        Assigns a task to a specific node.
        :param node_id: ID of the target node.
        :param task: Task data as a dictionary.
        """
        with self.lock:
            if node_id in self.nodes and self.node_states[node_id] == "idle":
                self.node_states[node_id] = "active"
                print(f"[NodeManager] Assigning task to '{node_id}': {task}")
                self.nodes[node_id].receive_message(task)
            else:
                print(f"[NodeManager] Node '{node_id}' is not available. Task added to queue.")
                self.task_queue.put((node_id, task))

    def assign_tasks_round_robin(self, tasks: List[Dict[str, Any]]):
        """
        Assigns tasks to nodes in a round-robin fashion.
        :param tasks: List of task dictionaries.
        """
        with self.lock:
            available_nodes = [node_id for node_id, state in self.node_states.items() if state == "idle"]
            if not available_nodes:
                print("[NodeManager] No available nodes. Adding tasks to queue.")
                for task in tasks:
                    self.task_queue.put(("unassigned", task))
                return

            for i, task in enumerate(tasks):
                target_node = available_nodes[i % len(available_nodes)]
                print(f"[NodeManager] Assigning task to '{target_node}': {task}")
                self.assign_task(target_node, task)

    def _monitor_node_health(self):
        """
        Monitors nodes' health and redistributes tasks if a node fails.
        """
        while True:
            time.sleep(self.task_processing_interval)
            with self.lock:
                for node_id, node in self.nodes.items():
                    # Simulate health checks using a random failure mechanism
                    if random.random() < 0.05:  # 5% chance a node fails
                        self.node_states[node_id] = "failed"
                        print(f"[NodeManager] Node '{node_id}' has failed. Redistributing tasks.")
                        self._recover_failed_node(node_id)
                    elif self.node_states[node_id] == "active":
                        # Simulate task completion
                        self.node_states[node_id] = "idle"
                        print(f"[NodeManager] Node '{node_id}' has completed its task and is now idle.")

    def _recover_failed_node(self, failed_node_id: str):
        """
        Handles a failed node by redistributing its tasks.
        :param failed_node_id: ID of the failed node.
        """
        # Simulate redistributing tasks from the failed node
        print(f"[NodeManager] Recovering tasks from failed node '{failed_node_id}'")
        self.node_states[failed_node_id] = "idle"

        while not self.task_queue.empty():
            node_id, task = self.task_queue.get()
            if node_id == "unassigned" or node_id == failed_node_id:
                self.assign_tasks_round_robin([task])

    def list_nodes(self):
        """
        Lists all nodes with their current states.
        """
        with self.lock:
            print("\n[NodeManager] Current Node States:")
            for node_id, state in self.node_states.items():
                print(f"  Node: {node_id}, State: {state}")
            print("")


# Example Usage
if __name__ == "__main__":
    manager = NodeManager()

    # Create nodes
    manager.create_node("Node_1")
    manager.create_node("Node_2")
    manager.create_node("Node_3")

    # Assign tasks
    manager.assign_task("Node_1", {"type": "task", "task": "Analyze Titanic data"})
    manager.assign_tasks_round_robin([
        {"type": "task", "task": "Explore iceberg patterns"},
        {"type": "task", "task": "Map passenger data"},
        {"type": "task", "task": "Analyze construction materials"},
    ])

    # Simulate monitoring for 20 seconds
    for _ in range(10):
        time.sleep(2)
        manager.list_nodes()

from modules.PerspectiveManager import PerspectiveManager
from modules.SeedManager import SeedManager
from modules.MirroredNetwork import MirroredNetwork

class NodeManager:
    def __init__(self):
        self.nodes = []  # List to store registered nodes
        self.perspective_manager = PerspectiveManager()
        self.seed_manager = SeedManager()
        self.mirrored_network = MirroredNetwork()

    def load_nodes(self):
        """
        Load initial nodes into the system and initialize networks.
        """
        print("Loading nodes...")
        self.nodes = [
            {"name": "TextProcessor", "status": "active"},
            {"name": "VisualProcessor", "status": "active"},
            {"name": "MemoryGraph", "status": "idle"},
        ]
        self.mirrored_network.initialize_networks(self.nodes)
        print(f"Nodes loaded: {len(self.nodes)} nodes initialized in mirrored networks.")

    def update_nodes(self):
        """
        Update the status of all nodes during each tick.
        """
        print("Updating nodes...")
        for node in self.nodes:
            if node["status"] == "active":
                print(f"Node {node['name']} is processing data...")
                # Example: Process perspectives for active nodes
                if node["name"] == "TextProcessor":
                    data = "Sample text data"
                    self.perspective_manager.process_perspectives(data)
            elif node["status"] == "idle":
                print(f"Node {node['name']} is waiting for tasks.")
        # Synchronize mirrored networks after updates
        self.mirrored_network.sync_networks()

    def register_node(self, name, parameters=None):
        """
        Dynamically register a new node using the seed manager.
        """
        seed = self.seed_manager.generate_seed(name, parameters)
        new_node = self.seed_manager.initialize_from_seed(name)
        self.nodes.append(new_node)
        print(f"Node '{name}' has been registered with parameters: {parameters}.")
