class KnowledgeIntegrator:
    """System for integrating knowledge across different capabilities"""
    def __init__(self):
        self.knowledge_graph = nx.DiGraph()
        self.confidence_threshold = 0.7
        self.integration_patterns = defaultdict(list)
        self.cross_references = defaultdict(set)

    def integrate_knowledge(self, new_knowledge: Dict, source_type: str):
        """Integrate new knowledge into the graph"""
        # Create new nodes for knowledge pieces
        for key, value in new_knowledge.items():
            if self._validate_knowledge(value):
                node_id = str(uuid.uuid4())
                self.knowledge_graph.add_node(
                    node_id,
                    content=value,
                    source_type=source_type,
                    timestamp=time.time()
                )
                
                # Find and create relationships
                self._create_relationships(node_id, value)
                
                # Update cross-references
                self._update_cross_references(node_id, value)

    def _validate_knowledge(self, knowledge: any) -> bool:
        """Validate new knowledge"""
        if isinstance(knowledge, dict):
            return knowledge.get('confidence', 0) > self.confidence_threshold
        return False

    def _create_relationships(self, node_id: str, knowledge: Dict):
        """Create relationships between knowledge nodes"""
        for existing_node in self.knowledge_graph.nodes():
            if existing_node != node_id:
                existing_knowledge = self.knowledge_graph.nodes[existing_node]['content']
                
                # Calculate relationship strength
                relationship = self._calculate_relationship(knowledge, existing_knowledge)
                
                if relationship['strength'] > 0.5:
                    self.knowledge_graph.add_edge(
                        node_id,
                        existing_node,
                        **relationship
                    )

    def _calculate_relationship(self, knowledge1: Dict, knowledge2: Dict) -> Dict:
        """Calculate relationship between two pieces of knowledge"""
        relationship = {'strength': 0.0, 'type': 'unknown'}
        
        # Check for direct references
        if any(str(v1) in str(v2) for v1 in knowledge1.values() 
               for v2 in knowledge2.values()):
            relationship['strength'] = 0.8
            relationship['type'] = 'direct_reference'
            
        # Check for pattern matches
        elif self._check_pattern_match(knowledge1, knowledge2):
            relationship['strength'] = 0.6
            relationship['type'] = 'pattern_match'
            
        # Check for temporal relationship
        elif self._check_temporal_relationship(knowledge1, knowledge2):
            relationship['strength'] = 0.5
            relationship['type'] = 'temporal'
            
        return relationship

    def query_knowledge(self, query: Dict) -> List[Dict]:
        """Query integrated knowledge"""
        results = []
        
        # Search through knowledge graph
        for node in self.knowledge_graph.nodes():
            node_data = self.knowledge_graph.nodes[node]
            
            # Check for matches
            if self._matches_query(node_data['content'], query):
                # Get related knowledge
                related = self._get_related_knowledge(node)
                
                results.append({
                    'primary_knowledge': node_data['content'],
                    'related_knowledge': related,
                    'confidence': node_data['content'].get('confidence', 0)
                })
                
        return sorted(results, key=lambda x: x['confidence'], reverse=True)

