from typing import Dict, List, Any, Optional
from datetime import datetime
import numpy as np
from collections import defaultdict

@dataclass
class LearningMetrics:
    """Tracks learning performance metrics."""
    pattern_accuracy: float = 0.0
    knowledge_coherence: float = 0.0
    insight_novelty: float = 0.0
    learning_rate: float = 0.1
    adaptation_score: float = 0.0
    timestamp: str = field(default_factory=lambda: datetime.now().isoformat())

class AutonomousLearning:
    """Manages the system's autonomous learning capabilities."""
    
    def __init__(self):
        self.pattern_weights = defaultdict(float)
        self.knowledge_connections = defaultdict(list)
        self.learning_history = []
        self.performance_metrics = []
        self.adaptation_threshold = 0.7
        
    def evaluate_performance(self, insights: List[Dict[str, Any]]) -> LearningMetrics:
        """Evaluates current system performance."""
        metrics = LearningMetrics()
        
        # Calculate pattern recognition accuracy
        metrics.pattern_accuracy = self._calculate_pattern_accuracy(insights)
        
        # Evaluate knowledge coherence
        metrics.knowledge_coherence = self._calculate_knowledge_coherence(insights)
        
        # Measure insight novelty
        metrics.insight_novelty = self._calculate_insight_novelty(insights)
        
        # Calculate adaptation score
        metrics.adaptation_score = self._calculate_adaptation_score(
            metrics.pattern_accuracy,
            metrics.knowledge_coherence,
            metrics.insight_novelty
        )
        
        self.performance_metrics.append(metrics)
        return metrics
        
    def adapt_parameters(self, metrics: LearningMetrics):
        """Adapts system parameters based on performance metrics."""
        if metrics.adaptation_score > self.adaptation_threshold:
            # Strengthen successful patterns
            self._strengthen_patterns()
            
            # Enhance knowledge connections
            self._enhance_connections()
            
            # Adjust learning rate
            self._adjust_learning_rate(metrics)
            
        self.learning_history.append({
            'timestamp': datetime.now().isoformat(),
            'metrics': metrics,
            'adaptations_made': metrics.adaptation_score > self.adaptation_threshold
        })
        
    def _calculate_pattern_accuracy(self, insights: List[Dict[str, Any]]) -> float:
        """Calculates accuracy of pattern recognition."""
        if not insights:
            return 0.0
            
        accuracies = []
        for insight in insights:
            if 'pattern_matches' in insight:
                accuracy = insight.get('confidence', 0.0)
                accuracies.append(accuracy)
                
                # Update pattern weights
                for pattern in insight.get('patterns', []):
                    self.pattern_weights[pattern['id']] += accuracy
                    
        return np.mean(accuracies) if accuracies else 0.0
        
    def _calculate_knowledge_coherence(self, insights: List[Dict[str, Any]]) -> float:
        """Evaluates coherence of knowledge connections."""
        if not insights:
            return 0.0
            
        coherence_scores = []
        for insight in insights:
            connections = insight.get('connections', [])
            if connections:
                # Calculate connection strength
                strength = np.mean([conn.get('weight', 0.0) for conn in connections])
                coherence_scores.append(strength)
                
                # Store connections
                self.knowledge_connections[insight['id']].extend(connections)
                
        return np.mean(coherence_scores) if coherence_scores else 0.0
        
    def _calculate_insight_novelty(self, insights: List[Dict[str, Any]]) -> float:
        """Measures novelty of generated insights."""
        if not insights:
            return 0.0
            
        novelty_scores = []
        for insight in insights:
            # Check if insight connects previously unconnected patterns
            connections = insight.get('connections', [])
            existing_connections = set()
            for src_id in self.knowledge_connections:
                for conn in self.knowledge_connections[src_id]:
                    existing_connections.add(
                        (conn.get('source'), conn.get('target'))
                    )
                    
            new_connections = 0
            for conn in connections:
                pair = (conn.get('source'), conn.get('target'))
                if pair not in existing_connections:
                    new_connections += 1
                    
            if connections:
                novelty = new_connections / len(connections)
                novelty_scores.append(novelty)
                
        return np.mean(novelty_scores) if novelty_scores else 0.0
        
    def _calculate_adaptation_score(
        self,
        pattern_accuracy: float,
        knowledge_coherence: float,
        insight_novelty: float
    ) -> float:
        """Calculates overall adaptation score."""
        weights = {
            'pattern_accuracy': 0.4,
            'knowledge_coherence': 0.4,
            'insight_novelty': 0.2
        }
        
        return (
            weights['pattern_accuracy'] * pattern_accuracy +
            weights['knowledge_coherence'] * knowledge_coherence +
            weights['insight_novelty'] * insight_novelty
        )
        
    def _strengthen_patterns(self):
        """Strengthens successful pattern recognition."""
        if not self.pattern_weights:
            return
            
        # Normalize pattern weights
        total_weight = sum(self.pattern_weights.values())
        if total_weight > 0:
            for pattern_id in self.pattern_weights:
                self.pattern_weights[pattern_id] /= total_weight
                
    def _enhance_connections(self):
        """Enhances strong knowledge connections."""
        for insight_id in self.knowledge_connections:
            connections = self.knowledge_connections[insight_id]
            for conn in connections:
                # Strengthen high-weight connections
                if conn.get('weight', 0.0) > 0.7:
                    conn['weight'] = min(1.0, conn['weight'] * 1.1)
                    
    def _adjust_learning_rate(self, metrics: LearningMetrics):
        """Adjusts learning rate based on performance."""
        if metrics.adaptation_score > 0.8:
            # Reduce learning rate when performing well
            metrics.learning_rate *= 0.95
        elif metrics.adaptation_score < 0.5:
            # Increase learning rate when performance is poor
            metrics.learning_rate = min(1.0, metrics.learning_rate * 1.05)
            
    def get_learning_summary(self) -> Dict[str, Any]:
        """Generates summary of learning progress."""
        if not self.performance_metrics:
            return {}
            
        recent_metrics = self.performance_metrics[-10:]
        
        return {
            'total_iterations': len(self.performance_metrics),
            'current_performance': {
                'pattern_accuracy': self.performance_metrics[-1].pattern_accuracy,
                'knowledge_coherence': self.performance_metrics[-1].knowledge_coherence,
                'insight_novelty': self.performance_metrics[-1].insight_novelty
            },
            'learning_trends': {
                'pattern_accuracy': self._calculate_trend([m.pattern_accuracy for m in recent_metrics]),
                'knowledge_coherence': self._calculate_trend([m.knowledge_coherence for m in recent_metrics]),
                'insight_novelty': self._calculate_trend([m.insight_novelty for m in recent_metrics])
            },
            'adaptation_rate': np.mean([
                1 if entry['adaptations_made'] else 0
                for entry in self.learning_history[-10:]
            ])
        }
        
    def _calculate_trend(self, values: List[float]) -> float:
        """Calculates trend in a series of values."""
        if len(values) < 2:
            return 0.0
        
        return (values[-1] - values[0]) / len(values)
import wikipedia
import requests
from bs4 import BeautifulSoup
import networkx as nx
import numpy as np
from typing import Dict, List, Set, Optional
from dataclasses import dataclass
import random
import time
from collections import deque

@dataclass
class Knowledge:
    topic: str
    content: str
    links: List[str]
    source: str
    timestamp: float
    depth: int

@dataclass
class Specialization:
    primary_topic: str
    subtopics: Set[str]
    confidence: float = 0.0

class LearningNode:
    def __init__(self, node_id: str, parent_knowledge: Optional[List[Knowledge]] = None):
        self.id = node_id
        self.memory_capacity = 1000  # Maximum knowledge units
        self.knowledge_base = []
        self.specialization = None
        self.birth_time = time.time()
        self.child_nodes = set()
        
        # Inherit knowledge from parent if provided
        if parent_knowledge:
            self.knowledge_base.extend(parent_knowledge)
            self._develop_specialization()

    def learn_from_wikipedia(self, starting_point: Optional[str] = None) -> Optional[str]:
        """
        Learn from Wikipedia, starting from either a random page or specific topic.
        Returns the last explored topic for potential continuation.
        """
        try:
            # Get random page if no starting point
            if not starting_point:
                page = wikipedia.random(1)
            else:
                page = starting_point
                
            wiki_page = wikipedia.page(page)
            
            # Extract main content and links
            knowledge = Knowledge(
                topic=wiki_page.title,
                content=wiki_page.content[:5000],  # Limit content size
                links=wiki_page.links,
                source="wikipedia",
                timestamp=time.time(),
                depth=len(self.knowledge_base)
            )
            
            # Check memory capacity
            if len(self.knowledge_base) >= self.memory_capacity:
                return self._create_child_node(knowledge)
                
            self.knowledge_base.append(knowledge)
            self._develop_specialization()
            
            # Choose next topic based on current interests
            next_topic = self._choose_next_topic(knowledge.links)
            return next_topic
            
        except wikipedia.exceptions.DisambiguationError as e:
            return random.choice(e.options)
        except Exception as e:
            print(f"Error learning topic: {e}")
            return None

    def _choose_next_topic(self, available_links: List[str]) -> Optional[str]:
        """
        Intelligently choose next topic based on current specialization and interests.
        """
        if not self.specialization or not available_links:
            return random.choice(available_links) if available_links else None
            
        # Filter links related to current specialization
        relevant_links = []
        for link in available_links:
            try:
                summary = wikipedia.summary(link, sentences=1)
                relevance_score = self._calculate_relevance(summary)
                if relevance_score > 0.5:
                    relevant_links.append(link)
            except:
                continue
                
        return random.choice(relevant_links) if relevant_links else random.choice(available_links)

    def _calculate_relevance(self, text: str) -> float:
        """
        Calculate relevance of text to current specialization.
        """
        if not self.specialization:
            return 0.0
            
        # Simple relevance calculation based on keyword matching
        keywords = set(self.specialization.primary_topic.lower().split())
        keywords.update(self.specialization.subtopics)
        
        text_words = set(text.lower().split())
        matches = keywords.intersection(text_words)
        
        return len(matches) / len(keywords) if keywords else 0.0

    def _develop_specialization(self):
        """
        Develop or update node specialization based on accumulated knowledge.
        """
        if not self.knowledge_base:
            return
            
        # Extract common themes from knowledge
        topics = []
        for knowledge in self.knowledge_base:
            topics.extend(knowledge.topic.split())
            
        # Find most common topic
        topic_counts = {}
        for topic in topics:
            topic_counts[topic] = topic_counts.get(topic, 0) + 1
            
        if topic_counts:
            primary_topic = max(topic_counts.items(), key=lambda x: x[1])[0]
            
            # Find related subtopics
            subtopics = set()
            for knowledge in self.knowledge_base:
                if primary_topic.lower() in knowledge.topic.lower():
                    subtopics.update(set(knowledge.topic.split()) - {primary_topic})
            
            self.specialization = Specialization(
                primary_topic=primary_topic,
                subtopics=subtopics,
                confidence=topic_counts[primary_topic] / len(self.knowledge_base)
            )

    def _create_child_node(self, overflow_knowledge: Knowledge) -> str:
        """
        Create a new node when memory capacity is reached.
        """
        # Create new node with inherited knowledge
        child_id = f"{self.id}_child_{len(self.child_nodes)}"
        inherited_knowledge = self.knowledge_base[-100:]  # Inherit last 100 knowledge units
        child_node = LearningNode(child_id, inherited_knowledge)
        
        # Add overflow knowledge to child
        child_node.knowledge_base.append(overflow_knowledge)
        
        # Update relationships
        self.child_nodes.add(child_node)
        
        return overflow_knowledge.links[0] if overflow_knowledge.links else None

class WikiLearningNetwork:
    def __init__(self):
        self.nodes = {}
        self.root_node = None
        self.graph = nx.Graph()

    def initialize_network(self):
        """Start the network with a root node"""
        root_id = "root"
        self.root_node = LearningNode(root_id)
        self.nodes[root_id] = self.root_node
        self.graph.add_node(root_id)

    def grow_network(self, steps: int):
        """Grow the network for a specified number of steps"""
        if not self.root_node:
            self.initialize_network()

        current_nodes = list(self.nodes.values())
        for _ in range(steps):
            for node in current_nodes:
                # Let each node learn
                next_topic = node.learn_from_wikipedia()
                
                # Check for new child nodes
                new_children = node.child_nodes - set(self.nodes.values())
                for child in new_children:
                    self.nodes[child.id] = child
                    self.graph.add_node(child.id)
                    self.graph.add_edge(node.id, child.id)
                    
                # Update visualization
                self._update_visualization()

    def _update_visualization(self):
        """Update network visualization"""
        plt.clf()
        pos = nx.spring_layout(self.graph)
        
        # Draw nodes with different colors based on specialization
        colors = []
        for node_id in self.graph.nodes():
            node = self.nodes[node_id]
            if node.specialization:
                colors.append(hash(node.specialization.primary_topic) % 20)
            else:
                colors.append(0)
                
        nx.draw(self.graph, pos, 
               node_color=colors,
               with_labels=True,
               node_size=[len(self.nodes[node_id].knowledge_base) * 10 for node_id in self.graph.nodes()],
               cmap=plt.cm.viridis)
        
        plt.title(f"Wiki Learning Network\nNodes: {len(self.nodes)}")
        plt.pause(0.1)

    def query_network(self, topic: str) -> List[Knowledge]:
        """Query the network for information about a specific topic"""
        relevant_knowledge = []
        
        for node in self.nodes.values():
            for knowledge in node.knowledge_base:
                if topic.lower() in knowledge.topic.lower() or topic.lower() in knowledge.content.lower():
                    relevant_knowledge.append(knowledge)
                    
        return sorted(relevant_knowledge, key=lambda x: x.timestamp, reverse=True)

