@dataclass
class GrowthLaws:
    """Fundamental laws governing network growth and interaction"""
    max_energy_capacity: float = 100.0
    min_split_energy: float = 80.0
    energy_transfer_rate: float = 0.2
    mutation_rate: float = 0.01
    memory_threshold: int = 1000
    connection_strength_decay: float = 0.05
    learning_rate: float = 0.1
    specialization_threshold: float = 0.7

@dataclass
class NodeGenes:
    """Genetic structure that determines node behavior"""
    knowledge_capacity: int
    energy_efficiency: float
    learning_rate: float
    connection_strength: float
    specialization_tendency: float
    mutation_chance: float

    @classmethod
    def create_initial(cls):
        return cls(
            knowledge_capacity=1000,
            energy_efficiency=1.0,
            learning_rate=0.1,
            connection_strength=0.5,
            specialization_tendency=0.3,
            mutation_chance=0.01
        )

    def mutate(self) -> 'NodeGenes':
        """Create mutated copy of genes"""
        if np.random.random() < self.mutation_chance:
            return NodeGenes(
                knowledge_capacity=max(100, self.knowledge_capacity * np.random.normal(1, 0.1)),
                energy_efficiency=max(0.1, self.energy_efficiency * np.random.normal(1, 0.1)),
                learning_rate=max(0.01, self.learning_rate * np.random.normal(1, 0.1)),
                connection_strength=max(0.1, self.connection_strength * np.random.normal(1, 0.1)),
                specialization_tendency=max(0.1, self.specialization_tendency * np.random.normal(1, 0.1)),
                mutation_chance=max(0.001, self.mutation_chance * np.random.normal(1, 0.1))
            )
        return self

class BaseNode:
    """Base class for both text and visual nodes"""
    def __init__(self, node_id: str = None, genes: NodeGenes = None):
        self.id = node_id or str(uuid.uuid4())
        self.genes = genes or NodeGenes.create_initial()
        self.birth_time = time.time()
        self.energy = 10.0
        self.memory = []
        self.connections: Dict[str, float] = {}  # node_id: connection_strength
        self.mirror_connection: Optional[str] = None  # ID of mirror node
        self.specialization: Dict[str, float] = defaultdict(float)

    def can_split(self) -> bool:
        """Determine if node should split based on multiple factors"""
        return (
            self.energy >= self.genes.knowledge_capacity * 0.8 and
            len(self.memory) >= self.genes.knowledge_capacity * 0.7 and
            max(self.specialization.values(), default=0) >= self.genes.specialization_tendency
        )

    def transfer_energy(self, target: 'BaseNode', amount: float):
        """Transfer energy to another node"""
        if self.energy >= amount:
            self.energy -= amount
            target.energy += amount * self.genes.energy_efficiency
            return True
        return False

