class Node:
    def __init__(self, node_id: str, energy: float, knowledge: float):
        self.node_id = node_id
        self.energy = energy
        self.knowledge = knowledge

class EnergyOptimizationManager:
    """
    Manages energy optimization across nodes in the environment.
    """
    def __init__(self, nodes: Dict[str, Node]):
        self.nodes = nodes

    def redistribute_energy(self):
        """
        Redistributes energy from high-energy nodes to low-energy nodes.
        """
        high_energy_nodes = [node for node in self.nodes.values() if node.energy > 70]
        low_energy_nodes = [node for node in self.nodes.values() if node.energy < 30]

        for low_node in low_energy_nodes:
            for high_node in high_energy_nodes:
                if high_node.energy > 70:
                    transfer_amount = min(20, high_node.energy - 70)
                    high_node.energy -= transfer_amount
                    low_node.energy += transfer_amount

                    logging.info(f"Transferred {transfer_amount} energy from {high_node.node_id} to {low_node.node_id}.")

    def optimize_energy_usage(self):
        """
        Reduces energy consumption for nodes with low task loads.
        """
        for node in self.nodes.values():
            if node.energy > 50 and node.knowledge < 20:
                energy_saving = node.energy * 0.1
                node.energy -= energy_saving
                logging.info(f"Node {node.node_id} reduced energy usage by {energy_saving} for optimization.")

    def identify_critical_nodes(self) -> List[str]:
        """
        Identifies nodes critical to system operations based on energy and knowledge.

        Returns:
            List[str]: List of critical node IDs.
        """
        critical_nodes = [
            node.node_id for node in self.nodes.values()
            if node.energy < 40 and node.knowledge > 50
        ]

        for node_id in critical_nodes:
            logging.warning(f"Critical node identified: {node_id}.")

        return critical_nodes

