import asyncio
import pandas as pd
import numpy as np
from typing import Dict, List, Optional, Union
from dataclasses import dataclass
from datetime import datetime
import logging
import json
from concurrent.futures import ThreadPoolExecutor
import queue

@dataclass
class ProcessingJob:
    """Represents a data processing job in the system."""
    job_id: str
    use_case: str
    data_source: Union[str, pd.DataFrame]
    priority: int
    created_at: datetime
    status: str = "pending"
    progress: float = 0.0
    results: Optional[Dict] = None
    error: Optional[str] = None

class EnterpriseIntegrationLayer:
    """
    Enterprise-grade integration layer for handling complex processing workflows.
    """
    def __init__(self, max_workers: int = 4):
        self.job_queue = queue.PriorityQueue()
        self.active_jobs: Dict[str, ProcessingJob] = {}
        self.completed_jobs: Dict[str, ProcessingJob] = {}
        self.executor = ThreadPoolExecutor(max_workers=max_workers)
        self.logger = logging.getLogger("enterprise_integration")
        
        # Initialize processors
        self.processors = self._initialize_processors()
        
        # Start background workers
        self.is_running = True
        self.worker_task = asyncio.create_task(self._process_queue())

    def _initialize_processors(self) -> Dict:
        """Initialize all available processors."""
        return {
            "quantum": QuantumSimulationProcessor(),
            "climate": ClimatePatternProcessor(),
            "protein": ProteinFoldingProcessor(),
            "financial": FinancialAnalysisProcessor(),
            "material": MaterialDiscoveryProcessor(),
            "supply_chain": SupplyChainOptimizer(),
            "security": SecurityPatternAnalyzer()
        }

    async def submit_job(self, 
                        data_source: Union[str, pd.DataFrame],
                        use_case: str,
                        priority: int = 1,
                        batch_size: Optional[int] = None) -> str:
        """
        Submits a new processing job to the system.
        
        Parameters:
            data_source: Either a DataFrame or path to data file
            use_case: Type of analysis to perform
            priority: Job priority (1-10, lower is higher priority)
            batch_size: Optional batch size for large datasets
        
        Returns:
            job_id: Unique identifier for the submitted job
        """
        job_id = f"job_{datetime.now().strftime('%Y%m%d_%H%M%S')}_{use_case}"
        
        job = ProcessingJob(
            job_id=job_id,
            use_case=use_case,
            data_source=data_source,
            priority=priority,
            created_at=datetime.now()
        )
        
        # Add to queue with priority
        await self.job_queue.put((priority, job))
        self.active_jobs[job_id] = job
        
        self.logger.info(f"Submitted job {job_id} for {use_case} processing")
        return job_id

    async def _process_queue(self):
        """Background worker for processing jobs from the queue."""
        while self.is_running:
            try:
                # Get next job from queue
                priority, job = await self.job_queue.get()
                
                # Process job
                try:
                    processor = self.processors.get(job.use_case)
                    if not processor:
                        raise ValueError(f"Unknown use case: {job.use_case}")

                    # Handle different data source types
                    data = self._load_data(job.data_source)
                    
                    # Process data
                    result = await self._process_data(processor, data, job)
                    
                    # Update job status
                    job.status = "completed"
                    job.results = result
                    
                except Exception as e:
                    job.status = "failed"
                    job.error = str(e)
                    self.logger.error(f"Error processing job {job.job_id}: {str(e)}")
                
                finally:
                    # Move to completed jobs
                    self.completed_jobs[job.job_id] = job
                    if job.job_id in self.active_jobs:
                        del self.active_jobs[job.job_id]

            except Exception as e:
                self.logger.error(f"Error in queue processing: {str(e)}")
            
            await asyncio.sleep(0.1)  # Prevent CPU overuse

    def _load_data(self, data_source: Union[str, pd.DataFrame]) -> pd.DataFrame:
        """Loads data from various sources."""
        if isinstance(data_source, pd.DataFrame):
            return data_source
        elif isinstance(data_source, str):
            return pd.read_csv(data_source)
        else:
            raise ValueError("Unsupported data source type")

    async def _process_data(self, processor, data: pd.DataFrame, job: ProcessingJob) -> Dict:
        """Processes data using the specified processor."""
        # Update progress periodically
        total_steps = len(data)
        for i in range(0, total_steps, max(1, total_steps // 100)):
            job.progress = i / total_steps * 100
            await asyncio.sleep(0)
        
        # Process data
        result = processor.process(data)
        return result

    async def get_job_status(self, job_id: str) -> Optional[Dict]:
        """Returns the current status of a job."""
        job = self.active_jobs.get(job_id) or self.completed_jobs.get(job_id)
        if not job:
            return None
            
        return {
            "job_id": job.job_id,
            "status": job.status,
            "progress": job.progress,
            "created_at": job.created_at.isoformat(),
            "error": job.error,
            "results_available": bool(job.results)
        }

    async def get_job_results(self, job_id: str) -> Optional[Dict]:
        """Returns the results of a completed job."""
        job = self.completed_jobs.get(job_id)
        if not job or job.status != "completed":
            return None
            
        return job.results

    def export_results(self, job_id: str, format: str = "json") -> bytes:
        """Exports job results in the specified format."""
        job = self.completed_jobs.get(job_id)
        if not job or not job.results:
            raise ValueError("No results available for export")
            
        if format == "json":
            return json.dumps(job.results, indent=2).encode()
        elif format == "csv":
            if isinstance(job.results.get("data"), pd.DataFrame):
                return job.results["data"].to_csv(index=False).encode()
        
        raise ValueError(f"Unsupported export format: {format}")

    async def shutdown(self):
        """Gracefully shuts down the integration layer."""
        self.is_running = False
        self.executor.shutdown(wait=True)
        await self.worker_task

# Example Usage
async def main():
    # Initialize integration layer
    integration = EnterpriseIntegrationLayer()
    
    # Submit some test jobs
    data = pd.DataFrame(np.random.rand(100, 10))
    
    job_id1 = await integration.submit_job(data, "quantum", priority=1)
    job_id2 = await integration.submit_job(data, "climate", priority=2)
    
    # Monitor job status
    while True:
        status1 = await integration.get_job_status(job_id1)
        status2 = await integration.get_job_status(job_id2)
        
        print(f"Job 1 Status: {status1}")
        print(f"Job 2 Status: {status2}")
        
        if status1["status"] == "completed" and status2["status"] == "completed":
            break
            
        await asyncio.sleep(1)
    
    # Get and export results
    results1 = await integration.get_job_results(job_id1)
    results2 = await integration.get_job_results(job_id2)
    
    print("Job 1 Results:", results1)
    print("Job 2 Results:", results2)
    
    # Shutdown
    await integration.shutdown()

