import plotly.graph_objects as go

def generate_interactive_graph(insights):
    """Generates an interactive graph visualization."""
    G = nx.Graph()

    # Add nodes and edges
    for i, insight in enumerate(insights):
        G.add_node(f"Node {i + 1}", label=insight)
        if i > 0:
            G.add_edge(f"Node {i}", f"Node {i + 1}")

    pos = nx.spring_layout(G)

    # Prepare Plotly data
    edge_x = []
    edge_y = []
    for edge in G.edges():
        x0, y0 = pos[edge[0]]
        x1, y1 = pos[edge[1]]
        edge_x.extend([x0, x1, None])
        edge_y.extend([y0, y1, None])

    node_x = []
    node_y = []
    node_text = []
    for node, coords in pos.items():
        node_x.append(coords[0])
        node_y.append(coords[1])
        node_text.append(G.nodes[node]["label"])

    # Create Plotly figure
    fig = go.Figure()
    fig.add_trace(go.Scatter(
        x=edge_x,
        y=edge_y,
        mode="lines",
        line=dict(width=1, color="gray"),
        hoverinfo="none"
    ))
    fig.add_trace(go.Scatter(
        x=node_x,
        y=node_y,
        mode="markers+text",
        marker=dict(size=10, color="blue"),
        text=node_text,
        hoverinfo="text"
    ))

    fig.update_layout(title="Interactive Graph Visualization", showlegend=False)
    fig.show()

