# Imaging Processor (Open Source)
# ============================================================
class ImagingProcessor:
    def __init__(self, model_name: str = "openai/clip-vit-base-patch32"):
        self.image_pipeline = pipeline("feature-extraction", model=model_name)
    
    def get_image_embeddings(self, image_url: str) -> torch.Tensor:
        response = requests.get(image_url)
        img = Image.open(BytesIO(response.content)).convert("RGB")
        features = self.image_pipeline(img)
        embeddings = torch.tensor(features).mean(dim=1)
        return embeddings

