class KaleidoscopeEngine:
    def __init__(self, gear_count: int = 50):
        self.gear_memory = [defaultdict(float) for _ in range(gear_count)]
        self.concept_graph = defaultdict(list)
    
    def add_concept_link(self, concept: str, related_concept: str):
        if related_concept not in self.concept_graph[concept]:
            self.concept_graph[concept].append(related_concept)
    
    def feed_concept(self, concept: str):
        self._fill_gear(0, concept)
        for i in range(1, len(self.gear_memory)):
            self._propagate_gear_fill(i)
    
    def _fill_gear(self, gear_index: int, concept: str):
        self.gear_memory[gear_index][concept] += random.uniform(0.1, 0.3)
        if self.gear_memory[gear_index][concept] > 1.0:
            self._trigger_pivot(gear_index, concept)
    
    def _trigger_pivot(self, gear_index: int, concept: str):
        related = self.concept_graph.get(concept, [])
        if related:
            pivot_concept = random.choice(related)
            pivot_gear = random.randint(0, gear_index)
            self.gear_memory[pivot_gear][pivot_concept] += random.uniform(0.2, 0.5)
    
    def _propagate_gear_fill(self, gear_index: int):
        prev_gear = gear_index - 1
        if prev_gear < 0:
            return
        prev_concepts = sorted(self.gear_memory[prev_gear].items(), key=lambda x: x[1], reverse=True)
        if prev_concepts:
            top_concept, level = prev_concepts[0]
            for rc in self.concept_graph.get(top_concept, []):
                self.gear_memory[gear_index][rc] += level * random.uniform(0.05, 0.1)
    
    def get_next_concept(self, current_concept: str) -> str:
        concept_scores = defaultdict(float)
        for gear in self.gear_memory:
            for c, lvl in gear.items():
                if c != current_concept:
                    concept_scores[c] += lvl
        if not concept_scores:
            return current_concept
        sorted_concepts = sorted(concept_scores.items(), key=lambda x: x[1], reverse=True)
        return sorted_concepts[0][0]

# ============================================================
# ThoughtNexus
