class ThoughtNexus:
    def __init__(self):
        self.global_knowledge = defaultdict(list)
    
    def aggregate_knowledge(self, nodes: List['Node']):
        for node in nodes:
            for concept, data_list in node.knowledge.items():
                for d in data_list:
                    if d not in self.global_knowledge[concept]:
                        self.global_knowledge[concept].append(d)
    
    def refine_knowledge(self):
        for concept in self.global_knowledge:
            self.global_knowledge[concept] = list(set(self.global_knowledge[concept]))
    
    def kaleidoscope_analysis(self, concept: str) -> Dict[str, Any]:
        data_entries = self.global_knowledge.get(concept, [])
        perspectives = {}
        perspectives["text_definitions"] = [entry for entry in data_entries if isinstance(entry, str)]
        perspectives["visual"] = [entry for entry in data_entries if "image:" in str(entry)]
        perspectives["contextual_links"] = [c for c in self.global_knowledge.keys() if concept in c]
        return perspectives

