from typing import List, Dict
import numpy as np

class KaleidoscopeEngine:
    """
    Core Kaleidoscope Engine for processing data, dynamically shifting logic paths,
    and evolving nodes into Pure Nodes through insights and feedback loops.
    """
    # Initialize 40 gears with dynamic weights
    logic_weights = {f"gear_{i}": 1.0 for i in range(1, 41)}

    @staticmethod
    def process_data_dumps(data_dumps: List[Dict]) -> List[Dict]:
        """
        Processes data dumps from nodes, dynamically shifting logic paths, and generating insights.
        """
        insights = []
        for dump in data_dumps:
            # Dynamically adjust logic paths
            for gear, weight in KaleidoscopeEngine.logic_weights.items():
                adjustment = np.random.uniform(-0.05, 0.05)
                KaleidoscopeEngine.logic_weights[gear] += adjustment

            # Generate insights
            insights.append({
                "node_id": dump["node_id"],
                "weighted_logic": dict(KaleidoscopeEngine.logic_weights),
                "insight": f"Processed with traits {dump['traits']} in {dump['cluster']} cluster"
            })
        return insights

    @staticmethod
    def transform_nodes_to_pure(nodes: List[Dict], insights: List[Dict]) -> List[Dict]:
        """
        Transforms nodes into Pure Nodes using pure insights and traits.
        """
        pure_nodes = []
        for node, insight in zip(nodes, insights):
            combined_traits = {
                k: (node["traits"].get(k, 0) + insight["weighted_logic"].get(k, 0)) / 2
                for k in KaleidoscopeEngine.logic_weights.keys()
            }
            pure_nodes.append({
                "node_id": f"pure_{node['node_id']}",
                "traits": combined_traits,
                "origin": f"Generated from Node {node['node_id']} and Pure Insight",
                "cluster": node["cluster"],
            })
        return pure_nodes

    @staticmethod
    def feedback_to_environment(insights: List[Dict]):
        """
        Feeds insights back into the environment, influencing logic paths and future processing.
        """
        for insight in insights:
            for gear in KaleidoscopeEngine.logic_weights:
                KaleidoscopeEngine.logic_weights[gear] += np.random.uniform(-0.01, 0.01)
        print("Environment updated with feedback from insights.")
