import importlib
import sys
from typing import Any

class ModuleCaller:
    """
    Handles dynamic resolution and loading of modules within the Kaleidoscope AI system.
    Ensures that interdependencies across modules are handled smoothly.
    """

    def __init__(self):
        self.module_cache = {}

    def resolve(self, module_path: str) -> Any:
        """
        Dynamically resolves and loads a module or class.
        :param module_path: The full path to the module and class (e.g., "module.submodule.ClassName").
        :return: The loaded module or class.
        """
        try:
            if module_path in self.module_cache:
                return self.module_cache[module_path]

            module_name, class_name = module_path.rsplit('.', 1)
            module = importlib.import_module(module_name)
            resolved_class = getattr(module, class_name)

            self.module_cache[module_path] = resolved_class
            return resolved_class

        except ModuleNotFoundError as e:
            print(f"Error: Module '{module_path}' not found.")
            raise e
        except AttributeError as e:
            print(f"Error: Class or function '{module_path}' not found in the module.")
            raise e
        except Exception as e:
            print(f"Unexpected error while resolving module '{module_path}': {e}")
            raise e

