import importlib
import sys
from pathlib import Path

class ModuleResolver:
    @staticmethod
    def resolve(module_name: str, fallback_path: str = None):
        """
        Dynamically imports a module or provides a fallback import path.
        :param module_name: The name of the module to resolve.
        :param fallback_path: An optional fallback path for the module.
        :return: The imported module or raises an ImportError.
        """
        try:
            return importlib.import_module(module_name)
        except ModuleNotFoundError:
            if fallback_path:
                sys.path.append(fallback_path)
                return importlib.import_module(module_name)
            else:
                raise ImportError(f"Module '{module_name}' could not be resolved.")
