def handle_molecular_data(smiles):
    """Processes molecular data."""
    mol = Chem.MolFromSmiles(smiles)
    if not mol:
        return None
    return {
        "MolecularWeight": Descriptors.MolWt(mol),
        "LogP": Descriptors.MolLogP(mol),
        "NumAtoms": mol.GetNumAtoms()
    }

