from typing import Dict, List
from core.organic_node import OrganicNode
from core.node_replication import NodeReplicator

class NetworkGrowthManager:
    """Manages the growth and evolution of the entire network"""

    def __init__(self, networks: Dict[str, List[OrganicNode]]):
        self.networks = networks  # Dictionary of networks (e.g., 'text', 'visual')

    def grow_network(self, network_type: str, steps: int = 1):
        """Grows a specific network by replicating nodes"""
        if network_type not in self.networks:
            raise ValueError(f"Unknown network type: {network_type}")

        for _ in range(steps):
            for node in list(self.networks[network_type]):
                if node.energy > 20 and len(node.long_term_memory) > 10:
                    replicator = NodeReplicator(node)
                    try:
                        child_node = replicator.replicate()
                        self.networks[network_type].append(child_node)
                    except Exception as e:
                        print(f"Replication failed for node {node.id}: {e}")

    def specialize_nodes(self, network_type: str):
        """Assigns specialization roles to nodes in a network"""
        if network_type not in self.networks:
            raise ValueError(f"Unknown network type: {network_type}")

        for node in self.networks[network_type]:
            # Example specialization logic based on node maturity
            if node.maturity > 0.8:
                node.specialization = "validator"
            elif node.energy > 30:
                node.specialization = "processor"
            else:
                node.specialization = "generalist"

    def prune_inactive_nodes(self, network_type: str):
        """Removes nodes that are inactive or out of resources"""
        if network_type not in self.networks:
            raise ValueError(f"Unknown network type: {network_type}")

        self.networks[network_type] = [
            node for node in self.networks[network_type] if node.energy > 0
        ]

