class PerspectiveManager:
    def process_perspectives(self, data):
        perspectives = {
            "original": data,
            "reversed": data[::-1],
            "uppercase": data.upper(),
            "split_analysis": data.split(),
        }
        return self.generate_combinations(perspectives)

    def generate_combinations(self, perspectives):
        combined = {}
        for key1, value1 in perspectives.items():
            for key2, value2 in perspectives.items():
                if key1 != key2:
                    combined[f"{key1}_{key2}"] = (value1, value2)
        return combined
