from typing import List, Dict

class ResourceManager:
    """
    Manages resource allocation and balancing across nodes in the system.
    """

    def __init__(self):
        self.global_energy_pool = 1000.0  # Total energy available for the system
        self.nodes = {}  # Dictionary of nodes and their energy levels

    def register_node(self, node_id: str, initial_energy: float = 100.0):
        """
        Registers a node with the resource manager.
        :param node_id: Unique identifier for the node.
        :param initial_energy: Initial energy assigned to the node.
        """
        if node_id in self.nodes:
            raise ValueError(f"Node {node_id} is already registered.")
        self.nodes[node_id] = initial_energy

    def distribute_energy(self, allocation_strategy: str = "equal"):
        """
        Distributes energy from the global pool to all registered nodes based on the allocation strategy.
        :param allocation_strategy: Strategy for energy allocation (e.g., "equal", "priority").
        """
        if allocation_strategy == "equal":
            energy_per_node = self.global_energy_pool / len(self.nodes)
            for node_id in self.nodes:
                self.nodes[node_id] += energy_per_node
            self.global_energy_pool = 0

        elif allocation_strategy == "priority":
            total_energy_requested = sum(self.nodes.values())
            for node_id, current_energy in self.nodes.items():
                priority_factor = current_energy / total_energy_requested
                energy_to_allocate = self.global_energy_pool * priority_factor
                self.nodes[node_id] += energy_to_allocate
            self.global_energy_pool = 0

        else:
            raise ValueError(f"Unknown allocation strategy: {allocation_strategy}")

    def request_energy(self, node_id: str, amount: float) -> bool:
        """
        Handles energy requests from a specific node.
        :param node_id: The ID of the requesting node.
        :param amount: The amount of energy requested.
        :return: True if the request is granted, False otherwise.
        """
        if self.global_energy_pool >= amount:
            self.global_energy_pool -= amount
            self.nodes[node_id] += amount
            return True
        return False

    def balance_energy(self):
        """
        Balances energy levels among all nodes to prevent failures.
        """
        average_energy = sum(self.nodes.values()) / len(self.nodes)
        for node_id in self.nodes:
            self.nodes[node_id] = average_energy

    def remove_node(self, node_id: str):
        """
        Removes a node from the resource manager.
        :param node_id: The ID of the node to remove.
        """
        if node_id in self.nodes:
            del self.nodes[node_id]

    def get_node_energy(self, node_id: str) -> float:
        """
        Retrieves the current energy level of a specific node.
        :param node_id: The ID of the node.
        :return: The energy level of the node.
        """
        return self.nodes.get(node_id, 0.0)

    def status(self) -> Dict[str, float]:
        """
        Provides a summary of the energy levels of all nodes and the global pool.
        :return: A dictionary containing the energy levels.
        """
        return {"global_pool": self.global_energy_pool, "nodes": self.nodes}

# Example usage
if __name__ == "__main__":
    manager = ResourceManager()

    # Register nodes
    manager.register_node("node_1", initial_energy=100.0)
    manager.register_node("node_2", initial_energy=200.0)

    print("Initial Status:", manager.status())

    # Distribute energy equally
    manager.distribute_energy(allocation_strategy="equal")
    print("After Equal Distribution:", manager.status())

    # Request energy for a node
    granted = manager.request_energy("node_1", 50.0)
    print(f"Energy request granted: {granted}")
    print("After Energy Request:", manager.status())

    # Balance energy
    manager.balance_energy()
    print("After Balancing Energy:", manager.status())

    # Remove a node
    manager.remove_node("node_2")
    print("After Removing Node:", manager.status())


