        print("\nAnalysis Complete!")
        print(f"Total Analysis Time: {total_duration}")
        print("\nResults Summary:")
        print("-" * 50)
        print(f"Total Knowledge Clusters: {sum(r['total_clusters'] for r in phase_results)}")
