import yaml
import json
from dataclasses import dataclass, field, asdict
from typing import Dict, List, Any, Optional
from pathlib import Path
import threading
from datetime import datetime
import logging

@dataclass
class SystemConfig:
    """System configuration settings."""
    # Memory Management
    memory_threshold: float = 0.8
    cache_size: int = 1000
    cleanup_interval: int = 3600  # seconds
    
    # Processing Settings
    batch_size: int = 100
    max_threads: int = 4
    processing_timeout: int = 300  # seconds
    
    # Learning Parameters
    learning_rate: float = 0.1
    exploration_rate: float = 0.2
    pattern_threshold: float = 0.7
    
    # Network Settings
    max_connections: int = 1000
    connection_timeout: int = 30  # seconds
    retry_attempts: int = 3
    
    # Storage Settings
    checkpoint_interval: int = 1800  # seconds
    max_checkpoints: int = 10
    storage_path: str = "data"

class SystemManager:
    """Manages system configuration and runtime behavior."""
    
    def __init__(self, config_path: Optional[str] = None):
        self.config = SystemConfig()
        self.config_path = config_path or "config/system.yaml"
        self.components = {}
        self.running_tasks = {}
        self.task_lock = threading.Lock()
        self.logger = logging.getLogger(__name__)
        
        # Load configuration if exists
        if Path(self.config_path).exists():
            self.load_config()
            
    def load_config(self):
        """Loads system configuration from file."""
        try:
            with open(self.config_path, 'r') as f:
                config_data = yaml.safe_load(f)
                
            # Update configuration
            for key, value in config_data.items():
                if hasattr(self.config, key):
                    setattr(self.config, key, value)
                    
            self.logger.info("Successfully loaded system configuration")
            
        except Exception as e:
            self.logger.error(f"Error loading configuration: {str(e)}")
            raise
            
    def save_config(self):
        """Saves current configuration to file."""
        try:
            config_dir = Path(self.config_path).parent
            config_dir.mkdir(exist_ok=True)
            
            with open(self.config_path, 'w') as f:
                yaml.dump(asdict(self.config), f)
                
            self.logger.info("Successfully saved system configuration")
            
        except Exception as e:
            self.logger.error(f"Error saving configuration: {str(e)}")
            raise
            
    def register_component(self, name: str, component: Any):
        """Registers a system component."""
        self.components[name] = {
            'instance': component,
            'status': 'registered',
            'registered_at': datetime.now().isoformat()
        }
        
    def start_component(self, name: str):
        """Starts a registered component."""
        if name not in self.components:
            raise ValueError(f"Component not registered: {name}")
            
        component = self.components[name]['instance']
        
        try:
            if hasattr(component, 'start'):
                component.start()
            self.components[name]['status'] = 'running'
            self.components[name]['started_at'] = datetime.now().isoformat()
            
            self.logger.info(f"Started component: {name}")
            
        except Exception as e:
            self.components[name]['status'] = 'error'
            self.components[name]['error'] = str(e)
            self.logger.error(f"Error starting component {name}: {str(e)}")
            raise
            
    def stop_component(self, name: str):
        """Stops a running component."""
        if name not in self.components:
            raise ValueError(f"Component not registered: {name}")
            
        component = self.components[name]['instance']
        
        try:
            if hasattr(component, 'stop'):
                component.stop()
            self.components[name]['status'] = 'stopped'
            self.components[name]['stopped_at'] = datetime.now().isoformat()
            
            self.logger.info(f"Stopped component: {name}")
            
        except Exception as e:
            self.components[name]['status'] = 'error'
            self.components[name]['error'] = str(e)
            self.logger.error(f"Error stopping component {name}: {str(e)}")
            raise
            
    def get_component_status(self, name: str) -> Dict[str, Any]:
        """Gets status of a component."""
        if name not in self.components:
            raise ValueError(f"Component not registered: {name}")
            
        return self.components[name]
        
    def get_system_status(self) -> Dict[str, Any]:
        """Gets overall system status."""
        return {
            'components': {
                name: info['status']
                for name, info in self.components.items()
            },
            'tasks': len(self.running_tasks),
            'config': asdict(self.config)
        }
        
    def update_config(self, updates: Dict[str, Any]):
        """Updates system configuration."""
        for key, value in updates.items():
            if hasattr(self.config, key):
                setattr(self.config, key, value)
                self.logger.info(f"Updated configuration: {key} = {value}")
                
        # Save updated configuration
        self.save_config()
        
        # Notify components of configuration change
        self._notify_config_change(updates)
        
    def _notify_config_change(self, updates: Dict[str, Any]):
        """Notifies components of configuration changes."""
        for name, component in self.components.items():
            if hasattr(component['instance'], 'handle_config_update'):
                try:
                    component['instance'].handle_config_update(updates)
                except Exception as e:
                    self.logger.error(
                        f"Error updating configuration for component {name}: {str(e)}"
                    )
                    
    def register_task(self, task_id: str, task_info: Dict[str, Any]):
        """Registers a running task."""
        with self.task_lock:
            self.running_tasks[task_id] = {
                'info': task_info,
                'started_at': datetime.now().isoformat(),
                'status': 'running'
            }
            
    def update_task_status(self, task_id: str, status: str, result: Any = None):
        """Updates status of a running task."""
        with self.task_lock:
            if task_id in self.running_tasks:
                self.running_tasks[task_id].update({
                    'status': status,
                    'completed_at': datetime.now().isoformat(),
                    'result': result
                })
                
    def get_task_status(self, task_id: str) -> Dict[str, Any]:
        """Gets status of a task."""
        return self.running_tasks.get(task_id, {})
        
    def cleanup_tasks(self):
        """Cleans up completed tasks."""
        with self.task_lock:
            completed_tasks = [
                task_id for task_id, info in self.running_tasks.items()
                if info['status'] in ['completed', 'failed']
            ]
            
            for task_id in completed_tasks:
                del self.running_tasks[task_id]

class ComponentManager:
    """Manages individual system components."""
    
    def __init__(self, system_manager: SystemManager):
        self.system_manager = system_manager
        self.component_configs = {}
        
    def create_component(self, component_type: str, config: Dict[str, Any]) -> Any:
        """Creates a new component instance."""
        if component_type not in COMPONENT_REGISTRY:
            raise ValueError(f"Unknown component type: {component_type}")
            
        # Create component instance
        component_class = COMPONENT_REGISTRY[component_type]
        component = component_class(**config)
        
        # Register with system manager
        self.system_manager.register_component(
            f"{component_type}_{len(self.component_configs)}",
            component
        )
        
        # Store configuration
        self.component_configs[component] = config
        
        return component
        
    def configure_component(self, component: Any, config: Dict[str, Any]):
        """Configures a component."""
        if component not in self.component_configs:
            raise ValueError("Unknown component")
            
        # Update configuration
        self.component_configs[component].update(config)
        
        # Apply configuration to component
        if hasattr(component, 'configure'):
            component.configure(config)
            
    def get_component_config(self, component: Any) -> Dict[str, Any]:
        """Gets configuration of a component."""
        return self.component_configs.get(component, {})

# Registry of available component types
COMPONENT_REGISTRY = {
    'memory_bank': MemoryBank,
    'knowledge_graph': KnowledgeGraph,
    'pattern_recognizer': PatternRecognizer,
    'insight_generator': InsightGenerator
}
import pandas as pd
import numpy as np
from typing import Dict
import logging
import time

class SystemTester:
    """
    Comprehensive test suite for the Kaleidoscope AI system.
    """
    def __init__(self):
        self.logger = logging.getLogger("system_tester")
        self.results = {}

    def run_drug_discovery_test(self):
        """Tests the drug discovery capabilities."""
        print("\n=== Running Drug Discovery Test ===")
        
        # Generate synthetic molecular data
        molecular_data = pd.DataFrame({
            'molecular_weight': np.random.normal(300, 50, 1000),
            'solubility': np.random.normal(2.5, 0.5, 1000),
            'binding_affinity': np.random.normal(-8.5, 1.0, 1000),
            'toxicity_score': np.random.normal(0.3, 0.1, 1000),
            'half_life': np.random.normal(24, 5, 1000)
        })

        # Test processing pipeline
        start_time = time.time()
        try:
            # Initialize processors
            engine = KaleidoscopeEngine()
            engine.add_memory_bank("DrugBank", capacity=50)

            # Process data
            processed_data = engine.process_data(molecular_data)
            clusters = engine.generate_clusters(processed_data, n_clusters=5)
            insights = engine.validate_insights(clusters)

            # Record results
            self.results['drug_discovery'] = {
                'success': True,
                'processing_time': time.time() - start_time,
                'clusters_found': len(set(clusters['cluster'])),
                'insights': insights
            }

            print("Drug Discovery Test Results:")
            print(f"- Processing Time: {self.results['drug_discovery']['processing_time']:.2f} seconds")
            print(f"- Clusters Found: {self.results['drug_discovery']['clusters_found']}")
            print("- Insights Generated:", len(insights))

        except Exception as e:
            self.results['drug_discovery'] = {
                'success': False,
                'error': str(e)
            }
            print(f"Error in drug discovery test: {e}")

    def run_performance_test(self):
        """Tests system performance and scalability."""
        print("\n=== Running Performance Test ===")
        
        sizes = [1000, 10000, 100000]
        for size in sizes:
            print(f"\nTesting with {size} data points...")
            
            # Generate test data
            test_data = pd.DataFrame(np.random.rand(size, 10))
            
            start_time = time.time()
            try:
                # Test processing
                engine = KaleidoscopeEngine()
                processed = engine.process_data(test_data)
                processing_time = time.time() - start_time

                memory_usage = processed.memory_usage().sum() / 1024**2  # MB

                self.results[f'performance_{size}'] = {
                    'success': True,
                    'processing_time': processing_time,
                    'memory_usage': memory_usage
                }

                print(f"- Processing Time: {processing_time:.2f} seconds")
                print(f"- Memory Usage: {memory_usage:.2f} MB")

            except Exception as e:
                self.results[f'performance_{size}'] = {
                    'success': False,
                    'error': str(e)
                }
                print(f"Error in performance test: {e}")

    def run_node_stability_test(self):
        """Tests node stability and energy management."""
        print("\n=== Running Node Stability Test ===")
        
        try:
            # Initialize nodes with different energy levels
            nodes = {
                f"Node-{i}": Node(f"Node-{i}", 
                                energy=np.random.uniform(20, 100),
                                knowledge=np.random.uniform(10, 50))
                for i in range(10)
            }

            # Create manager
            manager = NodeLifecycleManager()
            for node in nodes.values():
                manager.add_node(node)

            # Run stability tests
            start_time = time.time()
            initial_energies = {node_id: node.energy for node_id, node in nodes.items()}

            # Test node operations
            for _ in range(50):
                manager.check_inactive_nodes(threshold_minutes=1)
                manager.check_health()

            final_energies = {node_id: node.energy for node_id, node in nodes.items()}

            self.results['node_stability'] = {
                'success': True,
                'test_duration': time.time() - start_time,
                'energy_changes': {
                    node_id: {
                        'initial': initial_energies[node_id],
                        'final': final_energies[node_id]
                    }
                    for node_id in nodes.keys()
                }
            }

            print("Node Stability Test Results:")
            print(f"- Test Duration: {self.results['node_stability']['test_duration']:.2f} seconds")
            print(f"- Nodes Tested: {len(nodes)}")
            print("- Energy Stability:", sum(abs(final_energies[k] - initial_energies[k]) 
                                          for k in nodes.keys()) / len(nodes))

        except Exception as e:
            self.results['node_stability'] = {
                'success': False,
                'error': str(e)
            }
            print(f"Error in node stability test: {e}")

    def run_all_tests(self):
        """Runs all system tests."""
        print("Starting Comprehensive System Test\n")
        
        self.run_drug_discovery_test()
        self.run_performance_test()
        self.run_node_stability_test()
        
        print("\n=== Test Summary ===")
        success_count = sum(1 for r in self.results.values() if r.get('success', False))
        total_count = len(self.results)
        
        print(f"Tests Passed: {success_count}/{total_count}")
        print(f"Overall Success Rate: {(success_count/total_count)*100:.1f}%")

if __name__ == "__main__":
    # Run all tests
    tester = SystemTester()
    tester.run_all_tests()# File: system_monitoring.py

import pandas as pd
import numpy as np
import matplotlib.pyplot as plt
import time
import logging
from kaleidoscope_engine import KaleidoscopeEngine
from perspective_engine import PerspectiveEngine

# Configure logging
logging.basicConfig(
    filename="system_monitoring.log",
    level=logging.INFO,
    format="%(asctime)s - %(levelname)s - %(message)s"
)

def monitor_system():
    """
    Monitors the real-time operations of the Kaleidoscope AI system.
    Tracks memory usage, node activity, and performance metrics.
    """
    print("Starting System Monitoring...")

    # Simulate nodes and memory usage
    nodes = [f"Node-{i}" for i in range(10)]
    memory_usage = np.random.uniform(20, 80, size=len(nodes))
    energy_levels = np.random.uniform(50, 100, size=len(nodes))

    engine = KaleidoscopeEngine()
    perspective_engine = PerspectiveEngine()

    # Placeholder for dynamic metrics
    performance_metrics = {
        "timestamp": [],
        "average_memory": [],
        "average_energy": [],
        "task_completion_rate": []
    }

    for _ in range(10):  # Simulating 10 monitoring intervals
        current_time = time.strftime("%Y-%m-%d %H:%M:%S")
        average_memory = np.mean(memory_usage)
        average_energy = np.mean(energy_levels)

        # Simulate task completion
        task_completion_rate = np.random.uniform(0.7, 1.0)

        # Update performance metrics
        performance_metrics["timestamp"].append(current_time)
        performance_metrics["average_memory"].append(average_memory)
        performance_metrics["average_energy"].append(average_energy)
        performance_metrics["task_completion_rate"].append(task_completion_rate)

        logging.info(f"[{current_time}] Memory: {average_memory:.2f}%, Energy: {average_energy:.2f}%, Task Completion: {task_completion_rate:.2f}")

        # Simulate real-time changes
        memory_usage += np.random.uniform(-5, 5, size=len(nodes))
        energy_levels += np.random.uniform(-2, 2, size=len(nodes))
        memory_usage = np.clip(memory_usage, 0, 100)
        energy_levels = np.clip(energy_levels, 0, 100)

        time.sleep(1)  # Simulate time intervals

    # Convert metrics to DataFrame for visualization
    metrics_df = pd.DataFrame(performance_metrics)

    # Plot performance metrics
    plt.figure(figsize=(12, 6))
    plt.plot(metrics_df["timestamp"], metrics_df["average_memory"], label="Average Memory Usage", marker="o")
    plt.plot(metrics_df["timestamp"], metrics_df["average_energy"], label="Average Energy Levels", marker="s")
    plt.plot(metrics_df["timestamp"], metrics_df["task_completion_rate"], label="Task Completion Rate", marker="^")
