from typing import Dict
import numpy as np
from core.organic_node import OrganicNode
from learning.visual_processing import VisualProcessor

class VisualNetwork:
    """Manages the growth and interaction of visual nodes"""

    def __init__(self):
        self.nodes: Dict[str, OrganicNode] = {}
        self.processor = VisualProcessor()

    def add_node(self, node: OrganicNode):
        """Adds a new visual node to the network"""
        self.nodes[node.id] = node

    def process_image(self, image: np.ndarray):
        """Distributes image processing across nodes"""
        results = []
        for node in self.nodes.values():
            if node.energy > 0:
                features = self.processor.extract_features(image)
                matched_patterns = self.processor.match_patterns(features)
                node.process_information(str(features))  # Represent features as a string
                results.append({
                    "node_id": node.id,
                    "matched_patterns": matched_patterns,
                })
        return results

    def grow_network(self, steps: int = 1):
        """Simulates network growth by replicating nodes"""
        for _ in range(steps):
            for node in list(self.nodes.values()):
                if node.energy > 20 and len(node.long_term_memory) > 10:
                    replicator = NodeReplicator(node)
                    child_node = replicator.replicate()
                    self.add_node(child_node)
